// Pure (client-safe): the viewer's theme — appearance, palette, and an
// optional custom theme. Signed in, it's saved on the user
// (User.uiPreferences) and carried in the session token, so every device
// renders it on the first paint; a cookie holds the same compact string for
// signed-out pages. The colors live in src/app/theme.css (generated by
// scripts/generate-theme.ts); a custom theme's are built at request time
// (./custom.ts) through the same contrast-checked roles.

import { parseHex } from "./color";
import { customThemeCss } from "./custom";
import { NEUTRALS, PALETTES } from "./palettes.generated";
import type { SidebarStyle } from "./roles";

export { PALETTES };

export const APPEARANCES = ["system", "light", "dark"] as const;
export type Appearance = (typeof APPEARANCES)[number];
export type PresetId = (typeof PALETTES)[number]["id"];
export type PaletteId = PresetId | "custom";

export const APPEARANCE_LABELS: Record<Appearance, string> = { system: "System", light: "Light", dark: "Dark" };

export type NeutralTone = keyof typeof NEUTRALS;
export const NEUTRAL_TONES = Object.keys(NEUTRALS) as NeutralTone[];
export const NEUTRAL_TONE_LABELS: Record<NeutralTone, string> = { cool: "Cool", neutral: "Neutral", warm: "Warm" };
export const SIDEBAR_STYLES = ["light", "tinted", "dark"] as const satisfies readonly SidebarStyle[];
export const SIDEBAR_STYLE_LABELS: Record<SidebarStyle, string> = { light: "Light", tinted: "Tinted", dark: "Dark" };

// Three meaningful choices; everything else is derived and contrast-checked.
export interface CustomTheme {
  brand: string; // "#rrggbb"
  neutral: NeutralTone;
  sidebar: SidebarStyle;
}

export interface ThemePreference {
  appearance: Appearance;
  palette: PaletteId;
  custom?: CustomTheme;
  // When it was chosen (ms since epoch). The cookie and the saved account
  // theme can disagree — just after a save, or after a change on another
  // device — and the newer one wins (pickTheme).
  savedAt?: number;
}

export const THEME_COOKIE = "crm-theme";
export const DEFAULT_THEME: ThemePreference = { appearance: "system", palette: "forest" };
export const DEFAULT_CUSTOM: CustomTheme = { brand: "#1f7a5a", neutral: "cool", sidebar: "light" };
const ONE_YEAR_SECONDS = 365 * 24 * 60 * 60;

const isAppearance = (v: unknown): v is Appearance => typeof v === "string" && (APPEARANCES as readonly string[]).includes(v);
const isPreset = (v: unknown): v is PresetId => typeof v === "string" && PALETTES.some((p) => p.id === v);
const isTone = (v: unknown): v is NeutralTone => typeof v === "string" && (NEUTRAL_TONES as string[]).includes(v);
const isSidebar = (v: unknown): v is SidebarStyle => typeof v === "string" && (SIDEBAR_STYLES as readonly string[]).includes(v);

export function validCustom(v: unknown): CustomTheme | null {
  if (!v || typeof v !== "object") return null;
  const { brand, neutral, sidebar } = v as Record<string, unknown>;
  if (typeof brand !== "string" || !parseHex(brand) || !isTone(neutral) || !isSidebar(sidebar)) return null;
  return { brand: brand.toLowerCase(), neutral, sidebar };
}

// Anything unknown falls back to the default for that part; a "custom"
// palette without valid custom colors falls back to the default palette.
// Saved custom colors are kept even while a preset is chosen.
export function validTheme(v: unknown): ThemePreference {
  const o = v && typeof v === "object" ? (v as Record<string, unknown>) : {};
  const appearance = isAppearance(o.appearance) ? o.appearance : DEFAULT_THEME.appearance;
  const custom = validCustom(o.custom);
  const palette: PaletteId = o.palette === "custom" && custom ? "custom" : isPreset(o.palette) ? o.palette : DEFAULT_THEME.palette;
  const savedAt = typeof o.savedAt === "number" && Number.isFinite(o.savedAt) && o.savedAt > 0 ? Math.floor(o.savedAt) : undefined;
  return { appearance, palette, ...(custom ? { custom } : {}), ...(savedAt ? { savedAt } : {}) };
}

// Compact form for the cookie and session token:
//   "dark:coastal"  or  "light:custom:1f7a5a:warm:dark", plus "@<savedAt>"
export function encodeTheme(pref: ThemePreference): string {
  const base = `${pref.appearance}:${pref.palette}`;
  const body = pref.palette === "custom" && pref.custom ? `${base}:${pref.custom.brand.slice(1)}:${pref.custom.neutral}:${pref.custom.sidebar}` : base;
  return pref.savedAt ? `${body}@${pref.savedAt}` : body;
}

export function parseThemeCookie(value: string | undefined | null): ThemePreference {
  const [body = "", stamp] = decodeURIComponent(value ?? "").split("@");
  const [appearance, palette, brand, neutral, sidebar] = body.split(":");
  return validTheme({ appearance, palette, custom: brand ? { brand: `#${brand}`, neutral, sidebar } : undefined, savedAt: Number(stamp) });
}

// The account's saved theme (from the session) or this browser's cookie,
// whichever was chosen more recently; the account's on a tie.
export function pickTheme(sessionValue: string | undefined, cookieValue: string | undefined): ThemePreference {
  if (!sessionValue) return parseThemeCookie(cookieValue);
  if (!cookieValue) return parseThemeCookie(sessionValue);
  const fromSession = parseThemeCookie(sessionValue);
  const fromCookie = parseThemeCookie(cookieValue);
  return (fromCookie.savedAt ?? 0) > (fromSession.savedAt ?? 0) ? fromCookie : fromSession;
}

export function themeCookie(pref: ThemePreference): string {
  return `${THEME_COOKIE}=${encodeTheme(pref)}; Path=/; Max-Age=${ONE_YEAR_SECONDS}; SameSite=Lax`;
}

// User.uiPreferences is { version: 1, theme: {...} }; other keys (future
// navigation/workspace settings) are kept when the theme is saved. Unknown
// or malformed documents read as "no preference".
export const UI_PREFERENCES_VERSION = 1;

export function themeFromUiPreferences(doc: unknown): ThemePreference | null {
  if (!doc || typeof doc !== "object") return null;
  const { version, theme } = doc as Record<string, unknown>;
  return version === UI_PREFERENCES_VERSION && theme ? validTheme(theme) : null;
}

export function uiPreferencesWithTheme(doc: unknown, theme: ThemePreference): Record<string, unknown> {
  const current = doc && typeof doc === "object" && (doc as Record<string, unknown>).version === UI_PREFERENCES_VERSION ? (doc as Record<string, unknown>) : {};
  return {
    ...current,
    version: UI_PREFERENCES_VERSION,
    theme: { appearance: theme.appearance, palette: theme.palette, ...(theme.custom ? { custom: theme.custom } : {}), ...(theme.savedAt ? { savedAt: theme.savedAt } : {}) },
  };
}

export const CUSTOM_THEME_STYLE_ID = "custom-theme";

// Browser only: apply a choice to the open page at once (including a custom
// theme's colors, written into the one style element the root layout always
// renders) and remember it in this browser. Returns it stamped with now.
export function applyTheme(choice: ThemePreference): ThemePreference {
  const pref = { ...choice, savedAt: Date.now() };
  const root = document.documentElement;
  root.dataset.appearance = pref.appearance;
  root.dataset.palette = pref.palette;
  if (pref.palette === "custom" && pref.custom) {
    let style = document.getElementById(CUSTOM_THEME_STYLE_ID);
    if (!style) {
      style = document.createElement("style");
      style.id = CUSTOM_THEME_STYLE_ID;
      document.head.appendChild(style);
    }
    style.textContent = customThemeCss(pref.custom);
  }
  document.cookie = themeCookie(pref);
  return pref;
}
